var e=Object.freeze({full:`Back up private configuration, credentials and all supported saved assistant data.`,custom:`Choose which private sections to back up.`});function t(t){let n=t.querySelector(`#transfer-export-mode`),r=()=>{let r=n?.value||`full`,i=t.querySelector(`#transfer-export-description`);i&&(i.textContent=e[r]);let a=t.querySelector(`#transfer-custom-options`);a&&(a.hidden=r!==`custom`)};n&&!n.__eocExportOptionsBound&&(n.__eocExportOptionsBound=!0,n.addEventListener(`change`,r)),r()}var n=Object.freeze([[`configuration`,`Agent configuration and Function Tools`],[`request_rules`,`Request Rules`],[`persistent_memory`,`Persistent memories`],[`temporary_memory`,`Active temporary memories`],[`knowledge`,`Knowledge sources`],[`conversation_archive`,`Conversation archive`],[`usage`,`Usage history`],[`guest_mode`,`Guest Mode schedule`]]);function r(t=!1){return`<section class="page-intro"><h1>Export, Backup, Import & Restore</h1><p>Back up, restore, or move your assistant setup and saved data.</p></section><section class="content-card backup-surface">
    <div class="backup-panel transfer-panel" data-setting data-search="export backup import restore custom memories knowledge usage archive request rules">
    <div class="section-heading"><div><h2 id="transfer-export-heading">Export type</h2><p>Choose what you'd like to export.</p></div></div>
    <select id="transfer-export-mode" aria-labelledby="transfer-export-heading" aria-describedby="transfer-export-description"><option value="full">Full Backup (private)</option><option value="custom">Custom (private)</option></select>
    <p id="transfer-export-description" aria-live="polite">${e.full}</p>
    <div id="transfer-custom-options" class="setting-group" hidden><div class="subheading"><h3>Custom backup sections</h3><p>Selected sections are self-contained replacement sections when imported later.</p></div><div class="group-function-choices">${n.map(([e,t])=>`<label class="group-function-choice"><input type="checkbox" class="transfer-custom-section" value="${e}" checked><span><strong>${t}</strong></span></label>`).join(``)}</div></div>
    <p id="transfer-private-warning" class="notice warning" role="status">Included credentials and private data are <strong>not encrypted</strong>. Provider credentials are included when configuration is selected. Keep the file private and store it securely.</p>
    <div class="backup-actions"><button type="button" id="create-backup-transfer">Create export</button></div>
    ${t?`<small>Exports use saved configuration. Your unsaved changes are not included.</small>`:``}
    <hr>
    <div class="subheading"><h2>Import / Restore</h2><p>Choose a file to validate and review before restoring.</p></div>
    <div class="backup-actions"><button type="button" class="secondary" id="restore-backup-transfer">Choose file</button><input id="backup-file-transfer" type="file" accept="application/zip,.zip,application/json,.json" hidden></div>
    <p>Selected sections <strong>replace rather than merge</strong> destination data.</p>
  </div></section>`}export{t as n,r,n as t};